using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpRestServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor parameters are resolved from DI automatically.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get current weather for a location.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var response = await client.GetFromJsonAsync<JsonElement>(url);

        var current = response.GetProperty("current");
        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public async Task<string> GeocodeCityName(
        [Description("City name to look up")] string city)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";

        var response = await client.GetFromJsonAsync<JsonElement>(url);

        if (!response.TryGetProperty("results", out var results)
            || results.GetArrayLength() == 0)
        {
            return $"City '{city}' not found.";
        }

        var first = results[0];
        var name = first.GetProperty("name").GetString();
        var lat = first.GetProperty("latitude").GetDouble();
        var lon = first.GetProperty("longitude").GetDouble();

        return $"{name}: {lat}, {lon}";
    }
}

